func (q *Queries) SaveTicketStateOrder(ctx context.Context, arg SaveTicketStateOrderParams) error {
	_, err := q.db.Exec(ctx, saveTicketStateOrder, arg.Now, arg.WorkspaceID, arg.Ids)
	return err
}

